import {quote as q} from './validation.js';
const text=(name,label,value,help,required=true)=>({name,label,type:'text',default:value,help,required});
const num=(name,label,value,min,max,help)=>({name,label,type:'number',default:value,min,max,help,required:true});
const select=(name,label,value,options,help)=>({name,label,type:'select',default:value,options,help,required:true});
const verbose=v=>v.verbose?' -Verbose':'';
const base={category:'System Information',icon:'▦',risk:'read',versions:['5.1','7'],dependencies:[],parameters:[],essentials:true,outputType:'records',remote:true,requirements:'Windows; PowerShell 5.1 or 7. Run with permission to inspect the target computer.'};
const ad={category:'Active Directory',icon:'♧',dependencies:['ActiveDirectory'],remote:false,requirements:'RSAT ActiveDirectory module, reachable domain controller with AD Web Services, and directory permissions. PowerShell 7 requires a compatible RSAT module.'};
const server=()=>text('server','Domain controller','','Blank uses the current domain.',false);
const adServer=v=>v.server?.trim()?` -Server ${q(v.server)}`:'';
const eventParams=()=>[num('hours','Look back (hours)',24,1,8760,'Events are filtered at the source.'),num('limit','Maximum events',100,1,5000,'Bounded newest matching events.'),text('computer','Target computer','','Blank reads local logs; remote access requires Event Log firewall access.',false)];
const events=(v,log,ids,levels='')=>`try {\n    Get-WinEvent -FilterHashtable @{LogName=${log}; StartTime=(Get-Date).AddHours(-${Number(v.hours)})${ids?`; Id=@(${ids})`:''}${levels?`; Level=@(${levels})`:''}} -MaxEvents ${Number(v.limit)}${v.computer?.trim()?` -ComputerName ${q(v.computer)}`:''}${verbose(v)} -ErrorAction Stop\n} catch {\n    if ($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') { throw }\n}`;
const eventAction=(id,name,description,log,ids,keywords,admin=false,levels='')=>({...base,id,name,description,category:'Event Logs',icon:'◷',outputType:'events',admin,parameters:eventParams(),keywords,cmdlets:'Get-WinEvent',requirements:`Windows; event log read access${admin?'; Security audit policy and elevated access':''}. An empty match is a successful empty result. Remote reads need Event Log firewall access.`,generate:v=>`& {${events(v,log,ids,levels)}} |\n    Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message`});
