{id:'restore-point',name:'Create a workstation restore point',risk:'modify',admin:true,remote:false,outputType:'text',description:'Create a client Windows restore point. System Restore must be enabled; Windows normally limits creation to one point per 24 hours.',keywords:['create restore point','checkpoint computer','before maintenance'],cmdlets:'Checkpoint-Computer',parameters:[text('description','Restore point description','Before maintenance','Label for the restore point.')],requirements:'Elevated rights; client Windows only; System Restore enabled. Uses Windows PowerShell 5.1 via powershell.exe when exported for PowerShell 7. Does not support WhatIf.',generate:(v,version)=>{const code=`Checkpoint-Computer -Description ${q(v.description)} -RestorePointType MODIFY_SETTINGS${verbose(v)} -ErrorAction Stop`;return version==='7'?`powershell.exe -NoProfile -NonInteractive -Command ${q(`& { ${code} }`)}\nif ($LASTEXITCODE -ne 0) { throw 'Restore point creation failed.' }`:code;}},
{id:'reachable-hosts',name:'Filter to reachable hosts',category:'Networking',icon:'⌁',remote:false,outputType:'computers',description:'Check a comma-separated list of hosts with one ping each. ICMP failure can mean filtering; it does not prove a host is down.',keywords:['reachable hosts','fleet','many computers','targets list'],cmdlets:'Test-Connection',parameters:[text('hosts','Targets','localhost','Up to 50 comma-separated names; no shell expansion.')],generate:(v,version)=>`foreach ($ShellifyHost in @(${String(v.hosts).split(',').map(x=>q(x.trim())).join(', ')})) {\n    try {\n        if (Test-Connection -${version==='7'?'TargetName':'ComputerName'} $ShellifyHost -Count 1 -Quiet${verbose(v)} -ErrorAction Stop) { [pscustomobject]@{ComputerName=$ShellifyHost; Reachable=$true} }\n    } catch { Write-Warning ($ShellifyHost + ': ' + $_.Exception.Message) }\n}`},
{id:'report',name:'Export combined workflow report',category:'Reports',icon:'▱',remote:false,outputType:'file',report:true,description:'Combine earlier captured results into a report. HTML encodes result data; CSV uses a consistent Step, Target, Data envelope.',keywords:['report','html report','csv report','json report','export results'],cmdlets:'ConvertTo-Json · Export-Csv · ConvertTo-Html',parameters:[select('format','Report format','HTML',['HTML','CSV','JSON'],'Combines prior step results with their step number and target.'),text('path','Report path','reports/workflow.html','Parent folder must exist; existing files are not overwritten.')],requirements:'An existing writable parent folder. Always keep reports last. Results can include personal or operational data.',generate:v=>`$ShellifyCollected | ForEach-Object { [pscustomobject]@{Step=$_.Step; Target=$_.Target; Data=(ConvertTo-Json -InputObject $_.Data -Depth 6 -Compress${verbose(v)})} } | ${v.format==='CSV'?`Export-Csv -LiteralPath ${q(v.path)} -NoTypeInformation -Encoding UTF8 -NoClobber -ErrorAction Stop`:v.format==='JSON'?`ConvertTo-Json -Depth 6 | Out-File -LiteralPath ${q(v.path)} -Encoding UTF8 -NoClobber -ErrorAction Stop`:`ConvertTo-Html -Title 'Shellify workflow report' | Out-File -LiteralPath ${q(v.path)} -Encoding UTF8 -NoClobber -ErrorAction Stop`}`}
